 foreach($snapshot['sheetOrder'] as $sid){$s=&$snapshot['sheets'][$sid];$header=$s['cellData'][0]??[];$money=null;foreach($header as $c=>$cell)if(mb_strtoupper(trim((string)($cell['v']??'')),'UTF-8')==='TIỀN')$money=(int)$c;if($money===null||wb_time_column($s)!==0){unset($s);continue;}$rows=$s['rowCount'];$existing=[];foreach($s['cellData']??[] as $r=>$cells)if(!empty($cells[0]['custom']['victorTotal']))$existing[(int)$r]=$cells;
