  $total=$existing?end($existing):[];foreach($existing as $r=>$cells)unset($s['cellData'][$r]);$style=['bg'=>['rgb'=>'#00ff00'],'bl'=>1,'cl'=>['rgb'=>'#111111']];for($c=0;$c<$s['columnCount'];$c++)$total[$c]=array_merge($total[$c]??[],['s'=>$style]);$total[0]=['v'=>'TỔNG','t'=>1,'s'=>$style,'custom'=>['victorTotal'=>true]];foreach($header as $c=>$cell)if(mb_strtoupper(trim((string)($cell['v']??'')),'UTF-8')==='STT')$total[$c]=['v'=>'','s'=>$style];$n=$money+1;$column='';while($n){$n--;$column=chr(65+$n%26).$column;$n=intdiv($n,26);}$total[$money]=['f'=>'=SUM('.$column.'2:'.$column.$last.')','s'=>$style,'custom'=>['victorTotalFormula'=>true]];$s['cellData'][$last]=$total;unset($s);
